<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import{Head,router}from'@inertiajs/vue3';const props=defineProps<{comments:any}>();function moderate(c:any,action:string){const reason=action==='remove'?prompt('Moderation reason:'):'';if(action==='remove'&&!reason)return;router.post(route('admin.comments.moderate',c.id),{action,reason})}</script><template><Head title="Social comments"/><AdminLayout><h1 class="text-2xl font-bold">Social comments</h1><div class="mt-5 rounded-xl border bg-white"><div v-for="c in comments.data" :key="c.id" class="flex items-center gap-4 border-b p-4"><div class="flex-1"><b>{{c.user?.name}}</b><p>{{c.content}}</p><small class="text-slate-500">{{c.reports_count}} reports</small></div><button @click="moderate(c,c.deleted_at?'restore':'remove')" class="text-cyan-700">{{c.deleted_at?'Restore':'Remove'}}</button></div></div></AdminLayout></template>
